draw:
var pad = 30;
var Lx = W - 2 * pad;
var k = p.n * Math.PI / Lx;
var w = 1.8;
var A = H * 0.085;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

var topY = H * 0.28;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(pad, topY); ctx.lineTo(W - pad, topY); ctx.stroke();

ctx.lineWidth = 1.6;
ctx.strokeStyle = C.faint;
ctx.beginPath();
for (var i = 0; i <= 240; i++) {
  var x1 = pad + Lx * i / 240;
  var y1 = topY - A * Math.sin(k * (x1 - pad) - w * t);
  if (i === 0) { ctx.moveTo(x1, y1); } else { ctx.lineTo(x1, y1); }
}
ctx.stroke();

ctx.strokeStyle = C.figure;
ctx.beginPath();
for (var j = 0; j <= 240; j++) {
  var x2 = pad + Lx * j / 240;
  var y2 = topY - A * Math.sin(k * (x2 - pad) + w * t);
  if (j === 0) { ctx.moveTo(x2, y2); } else { ctx.lineTo(x2, y2); }
}
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("two travelling waves, opposite directions", pad, H * 0.09);

var by = H * 0.74;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(pad, by); ctx.lineTo(W - pad, by); ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
for (var s = -1; s <= 1; s += 2) {
  ctx.beginPath();
  for (var m = 0; m <= 240; m++) {
    var x3 = pad + Lx * m / 240;
    var y3 = by - s * 2 * A * Math.sin(k * (x3 - pad));
    if (m === 0) { ctx.moveTo(x3, y3); } else { ctx.lineTo(x3, y3); }
  }
  ctx.stroke();
}
ctx.setLineDash([]);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var q = 0; q <= 240; q++) {
  var x4 = pad + Lx * q / 240;
  var y4 = by - 2 * A * Math.sin(k * (x4 - pad)) * Math.cos(w * t);
  if (q === 0) { ctx.moveTo(x4, y4); } else { ctx.lineTo(x4, y4); }
}
ctx.stroke();

ctx.fillStyle = C.ink;
for (var nd = 0; nd <= p.n; nd++) {
  var xn = pad + Lx * nd / p.n;
  ctx.beginPath(); ctx.arc(xn, by, 3.5, 0, 6.2832); ctx.fill();
}
ctx.fillText("their sum: nothing travels", pad, H * 0.56);
ctx.fillText("node", pad + Lx / p.n - 14, by + 16);
ctx.fillText("antinode", pad + Lx / (2 * p.n) - 22, by - 2 * A - 8);

var lam = 2 * p.L / p.n;
out.note = "n = " + p.n + " loops on L = " + p.L.toFixed(2) + " m: wavelength = " + lam.toFixed(3) + " m, nodes every " + (lam / 2).toFixed(3) + " m";
